function b({registerIndicator:d,sourceValues:N,nulls:y}){const f=(o,l)=>{const a=o.length,c=new Array(a).fill(NaN),m=new Array(l).fill(NaN);let i=0,n=0,t=0,r=0,e=0;for(let s=0;s<a;s++){const h=m[i],u=Number.isFinite(o[s])?o[s]:0;if(Number.isFinite(h)){const M=n;n-=h,n+=u,t=t-M+l*u}else r+=1,n+=u,t=t+r*u,e=r*(r+1)*.5;m[i]=u,i=(i+1)%l,c[s]=e>0?t/e:NaN}return c};d({id:"oa-hma",name:"Hull Moving Average (HMA)",category:"Trends FIR",placement:"onchart",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"hma",type:"line",title:"HMA",style:{color:"#ffeb3b",lineWidth:2}}],calc(o,l){const a=Math.max(1,Math.floor(Number(l.period)||10)),c=N(o,l.source??"close"),m=Math.max(1,Math.round(a/2)),i=Math.max(1,Math.round(Math.sqrt(a))),n=f(c,m),t=f(c,a),r=new Array(o.length).fill(NaN);for(let e=0;e<o.length;e++)!Number.isFinite(n[e])||!Number.isFinite(t[e])||(r[e]=2*n[e]-t[e]);return{hma:y(f(r,i))}}})}export{b as default};
